def transform(grid):
    n = len(grid)
    anchors = [(i, row[0]) for i, row in enumerate(grid) if row[0] != 0]
    period = len(anchors)
    pattern = {}
    for i, color in anchors:
        pattern[i % period] = color
    return [[pattern[r % period]] * len(grid[0]) for r in range(n)]
